/* Finite, interruptible motion. No timers or rendering loops while idle. */
const Motion=(()=>{
  const reduce=matchMedia('(prefers-reduced-motion: reduce)');
  const spring='cubic-bezier(.16,1,.3,1)';
  const active=new Set();let observer=null,frame=0,pointer=null,drag=null,dismiss=null;
  const touch=matchMedia('(max-width:600px), (pointer:coarse)');
  const enabled=()=>!reduce.matches&&!document.hidden;
  function animate(el,frames,options={}){if(!el||!enabled())return null;const a=el.animate(frames,{duration:560,easing:spring,...options,...(touch.matches?{duration:Math.min(options.duration||260,280),delay:0}:{} )});active.add(a);a.finished.catch(()=>{}).finally(()=>active.delete(a));return a;}
  function capture(){return null;}
  function page(){if(!enabled())return;const el=document.querySelector('#app-content>.page');if(!el)return;el.getAnimations().forEach(a=>a.cancel());animate(el,[{opacity:.86,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,.6,.3,1)'});}
  function observe(){observer?.disconnect();document.querySelectorAll('.motion-await').forEach(el=>el.classList.remove('motion-await'));}
  function origin(selector){if(!enabled()||touch.matches||document.querySelector('dialog')?.open)return null;const el=document.querySelector(selector);if(!el)return null;const r=el.getBoundingClientRect();const host=document.querySelector('#app-content').getBoundingClientRect();if(r.bottom<host.top||r.top>host.bottom)return null;return {left:r.left,top:r.top,width:r.width,height:r.height};}
  function morph(rect,selector){if(!rect||!enabled())return;const dialog=document.querySelector('#app-dialog');const target=dialog.querySelector(selector);if(!target)return;dialog.getAnimations().forEach(a=>a.cancel());const r=target.getBoundingClientRect();const scale=dialog.getBoundingClientRect().width/dialog.offsetWidth;const dx=(rect.left-r.left)/scale,dy=(rect.top-r.top)/scale;const sx=rect.width/r.width,sy=rect.height/r.height;target.style.transformOrigin='0 0';animate(target,[{transform:`translate(${dx}px,${dy}px) scale(${sx},${sy})`,opacity:.8,borderRadius:'22px'},{transform:'translate(0,0) scale(1)',opacity:1,borderRadius:'18px'}],{duration:650});animate(dialog,[{opacity:.4},{opacity:1}],{duration:180});const body=target.parentElement;[...body.children].filter(el=>el!==target).forEach((el,i)=>animate(el,[{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:500,delay:120+Math.min(i,5)*30}));}
  function nav(){const nav=document.querySelector('#bottom-nav');const activeButton=nav?.querySelector('button.active');if(!activeButton)return;let blob=nav.querySelector('.nav-liquid');if(!blob){blob=document.createElement('i');blob.className='nav-liquid';blob.setAttribute('aria-hidden','true');nav.prepend(blob);}const span=activeButton.querySelector('span');const x=activeButton.offsetLeft+(activeButton.offsetWidth-43)/2;blob.style.transform=`translateX(${x}px)`;animate(span,[{scale:'.82'},{scale:'1.09',offset:.6},{scale:'1'}],{duration:510});}
  function success(button){if(!enabled()||!button)return;if(touch.matches){animate(button,[{scale:'.98'},{scale:'1'}],{duration:220});return;}animate(button,[{scale:'1'},{scale:'.96',offset:.18},{scale:'1.025',offset:.52},{scale:'1'}],{duration:580});let mark=document.createElement('span');mark.className='motion-success-ring';mark.setAttribute('aria-hidden','true');button.style.position='relative';button.append(mark);const a=animate(mark,[{opacity:.7,transform:'scale(.7)'},{opacity:0,transform:'scale(1.3)'}],{duration:640});a?.finished.catch(()=>{}).finally(()=>mark.remove());}
  document.addEventListener('pointerdown',e=>{if(!enabled())return;const handle=e.target.closest('.dialog-handle');if(handle){drag={pointer:e.pointerId,y:e.clientY,dy:0,dialog:handle.closest('dialog'),handle};handle.setPointerCapture(e.pointerId);return;}const b=e.target.closest('button');if(!b||b.disabled||b.classList.contains('city-marker'))return;animate(b,[{scale:'1'},{scale:'.965'}],{duration:110,easing:'ease-out'});},{passive:true});
  document.addEventListener('pointermove',e=>{if(!enabled())return;if(drag&&drag.pointer===e.pointerId){const scale=drag.dialog.getBoundingClientRect().width/drag.dialog.offsetWidth;drag.dy=Math.max(0,(e.clientY-drag.y)/scale);drag.dialog.style.translate=`0 ${Math.min(190,drag.dy)*.8}px`;return;}if(touch.matches||e.pointerType!=='mouse')return;const scene=e.target.closest('.discovery');if(!scene)return;pointer={scene,x:e.clientX,y:e.clientY};if(frame)return;frame=requestAnimationFrame(()=>{frame=0;if(!pointer?.scene.isConnected)return;const {scene,x,y}=pointer;const r=scene.getBoundingClientRect();const nx=(x-r.left)/r.width,ny=(y-r.top)/r.height;scene.style.setProperty('--motion-x',((nx-.5)*3).toFixed(2)+'px');scene.style.setProperty('--motion-y',((ny-.5)*2).toFixed(2)+'px');scene.style.setProperty('--light-x',(nx*100).toFixed(1)+'%');scene.style.setProperty('--light-y',(ny*100).toFixed(1)+'%');});},{passive:true});
  document.addEventListener('pointerout',e=>{const scene=e.target.closest('.discovery');if(!scene||scene.contains(e.relatedTarget))return;scene.style.setProperty('--motion-x','0px');scene.style.setProperty('--motion-y','0px');});
  function release(){if(!drag)return;const {dialog,dy}=drag;drag=null;if(dy>80&&dismiss){dismiss();return;}animate(dialog,[{translate:dialog.style.translate||'0 0'},{translate:'0 0'}],{duration:480});dialog.style.translate='';}
  document.addEventListener('pointerup',release);document.addEventListener('pointercancel',release);
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!enabled())return;if(['add-basket','redeem','favorite'].includes(b.dataset.action))success(b);},true);
  function stop(){for(const a of active)a.cancel();active.clear();cancelAnimationFrame(frame);frame=0;pointer=null;observer?.disconnect();document.querySelectorAll('.motion-old-page,.motion-success-ring').forEach(el=>el.remove());document.querySelectorAll('.motion-await').forEach(el=>el.classList.remove('motion-await'));if(drag)drag.dialog.style.translate='';drag=null;}
  reduce.addEventListener('change',()=>{if(reduce.matches)stop();else observe();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else observe();});
  return {capture,page,observe,origin,morph,nav,success,setDismiss:fn=>dismiss=fn,closed:()=>{const d=document.querySelector('#app-dialog');if(d)d.style.translate='';},animate};
})();
